#!/usr/bin/env python3
"""S2: generates h2/simH2.py (Rev H2 MuJoCo model) from the live cmp/simH.py (the other agent's Rev H model, untouched).
Every edit is a checked string replacement. Rev H2 numbers come from revH2/sim/params.py (ROBOT, MASS_ITEMS) of the handover:
  drive 318 mm wheels at 0.97 m track; 260 mm castors at x 0.82, track 0.60; tail anti-tip wheels (x -0.40, track 0.81, 75 mm up);
  rails 0.66 m clear, flared mouth 0.78 m, tips at x -0.43; nose tip 0.96; mast 0.53;
  carriage: B2's 640 mm self-aligning comb (fw_pivot as b2/simB2.py: yaw +/-4, roll +/-3 deg, centring springs 60 / 400 N m/rad),
  75 mm deep plate (640 x 75 x 6), comb (nib top) travel 0.80-1.20 m (400 mm stroke), 4 kN actuator;
  FIXED rest pad 400 x 120 mm on the carriage, 0.50 m below the comb, face pad_setback behind the comb seat line
  (seat line = front wall + 12 mm, params COMB_SEAT_OFFSET), default 0.025 m; env H2_PADGAP=<m> sets the pad so the nominal
  wall-to-pad gap at pad height on the bin being run is that value (S4);
  no handle keeper (H2_KEEPER=1: rim keeper bar for S5 only).
Firmware (DESIGN_RevH2.md s.3): the gate approach F1/F2/F6/F9 unchanged (squaring contact may be the pad); lift until load-on
(60 N rise + seat switch), rim-catch abort if load-on is > 25 mm below the expected ledge; FH1: keep lifting until BOTH bin-wheel
clearance sensors read clear (>= 60 mm, sigma 5 mm each) and the comb has risen >= 100 mm from load-on, stop at the stroke end;
FH2: claim only if load rise > 60 N AND seat switch AND both clearance sensors clear, else lower and report a safe miss.
Set-down: SD2 (as simH). Mass: params.MASS_ITEMS; each donor drive unit split 3.0 kg wheel/tyre/hub on the wheel body and the
rest (motor, gearbox, brake) on the chassis aft so the total CG matches params.robot_mass()."""
import os
H=os.path.dirname(os.path.abspath(__file__)); src=open(os.path.join(H,'..','cmp','simH.py')).read()
def rep(a,b,n=1):
    global src; c=src.count(a); assert c==n,(a[:90],c); src=src.replace(a,b)
# ---- header / paths
rep('"""REV H MuJoCo model','"""[H2] GENERATED by h2/make_simH2.py from cmp/simH.py (see that script for every change). Original docstring:\nREV H MuJoCo model')
rep("HERE=os.path.dirname(os.path.abspath(__file__)); G6=os.path.join(HERE,'..','..','g6'); sys.path.insert(0,G6)",
    "HERE=os.path.dirname(os.path.abspath(__file__)); G6=os.path.join(HERE,'..','..','g6'); sys.path.insert(0,G6); sys.path.insert(0,HERE)\n"
    "import hull_h2 as HH\nHULL=HH.HULL(); KEEPER2=os.environ.get('H2_KEEPER')=='1'\n"
    "PARAMS=os.path.join(HERE,'..','..','..','..','revH2_ext','BinTug_handover_2026-11-12','revH2','sim')")
# ---- geometry
a=src.find("GEO=dict(track=0.485"); b=src.find("# [D7]",a); assert a>0 and b>a
src=src[:a]+'''GEO=dict(track=0.485, rw=0.159, ww=0.035, cx=0.82, cy=0.30, cr=0.13, guard_y=0.33, guard_x0=-0.23, guard_x1=0.50, tail_x=-0.40, tail_y=0.405, tail_r=0.05, tail_gap=0.075, leg_tip=-0.43, mouth=0.78,
         face_x=0.529, tooth_len=0.075, nib_l=0.012, nib_h=0.020, tooth_hw=0.12, approach_nib_z=0.865, lift_range=0.40,
         pad_x=0.235, pad_z=0.45, pad_k=300000.0, pad_pre=0.0, pad_stroke=0.003, lift_extra=0.075, act_N=4000.0,
         tcap=60.0, kvs=1.0, car_zero=0.800, pad_in=0.013, pad_dz=0.50, pad_ret=0.0, rim_off=0.025, creep_v=0.03, creep_gap=0.06, lift_extra1=0.10,
         nib_l1=0.008, tooth_hw1=0.32, keep_l=0.080, yaw_sigma=1.0, yaw_ok=1.5, pad_setback=0.025, pad_hw=0.20, pad_hh=0.06, pad_mu=0.3,
         wclr=0.060, wclr_sig=0.005, fh1_rise=0.100, rimcatch=0.025, car_dz=-0.18)
# [H2] face_x = front wall at x 0.45 (params pad_x) + 4 mm ToF stop + 75 mm comb plate; car_zero = comb 0.80 m; lift_range 0.40 (0.80-1.20 m)
# [H2] pad_in = pad_setback - 0.012 (seat line 12 mm ahead of the wall, params COMB_SEAT_OFFSET); car_dz: carriage CG 0.20 m below the comb top
'''+src[b:]
rep("GEO.update(json.loads(os.environ.get('CGB_GEO','{}'))); GEO['lift_range']=0.30",
    "GEO.update(json.loads(os.environ.get('CGB_GEO','{}'))); GEO['pad_in']=GEO['pad_setback']-0.012")
rep("CORNERS=[(0.88,0.40),(0.88,-0.40),(0.0,0.52),(0.0,-0.52),(-0.43,0.52),(-0.43,-0.52)]   # params/mission.turning(): nose tip 0.88 (half 0.40), drive wheels and leg tips half 1.04/2",
    "CORNERS=[(0.96,0.45),(0.96,-0.45),(0.89,0.52),(0.89,-0.52),(0.0,0.52),(0.0,-0.52),(-0.43,0.44),(-0.43,-0.44)]+[(0.82+0.18*math.cos(t),sg*0.30+0.18*math.sin(t)) for sg in (1,-1) for t in [k*math.pi/6 for k in range(12)]]   # [H2] nose 0.96 with 70 mm chamfers, drive wheels half 0.52, flared tips, 260 mm castor swivel circles r 0.18")
# ---- mass
rep("MASSF=os.environ.get('CGB_MASSF',os.path.join(HERE,'mass_revH.json'))","MASSF=os.environ.get('CGB_MASSF',os.path.join(HERE,'mass_revH2.json'))")
rep("    sys.path.insert(0,os.path.join(HERE,'..','..','..','..','revH_ext','revH','sim')); import params as PH","    sys.path.insert(0,PARAMS); import params as PH")
rep("""        if n.startswith('Donor drive'):
            for s in (1,-1): rows.append(dict(name=n+(' L' if s>0 else ' R'),kg=k/2,p=[x,s*R['drive_track']/2,z],d=[0.3,0.12,0.3],g='wheel'))""",
"""        if n.startswith('Donor drive'):   # [H2] wheel+tyre+hub 3.0 kg on the wheel body (x 0), the rest aft on the chassis -> same CG as params
            for s in (1,-1):
                rows.append(dict(name=n+' wheel/tyre/hub'+(' L' if s>0 else ' R'),kg=3.0,p=[0.0,s*R['drive_track']/2,R['drive_r']],d=[0.3,0.12,0.3],g='wheel'))
                km=k/2-3.0; xm=(k/2*x-3.0*0.0)/km; zm=(k/2*z-3.0*R['drive_r'])/km
                rows.append(dict(name=n+' motor/gearbox/brake'+(' L' if s>0 else ' R'),kg=km,p=[xm,s*(R['drive_track']/2-0.10),zm],d=[0.25,0.12,0.15],g='chassis'))""")
rep("    car=[dict(name='Carriage, comb blade, pads (params)',kg=4.5,p=[0.40,0,0.90],d=[0.1,0.6,0.5],g='lift')]",
    "    cc=[i for i in PH.MASS_ITEMS if i[0].startswith('Carriage')][0]\n    car=[dict(name=cc[0],kg=cc[1],p=[cc[2],0,cc[3]],d=[0.1,0.64,0.6],g='lift')]")
rep("json.dump(dict(label='revH',","json.dump(dict(label='revH2',")
# ---- bin params
rep("    p['lip_w']=EN840_RW[binkey]                      # Rev H premise: full EN 840 receiver width on the front wall\n    p['xlip']=-(p['bar_x']+p['bar_r']-p['D']+0.02)    # front wall at rim height, bin frame mirrored (front -> +x)\n    return p",
    "    p['lip_w']=EN840_RW[binkey]                      # Rev H premise: full EN 840 receiver width on the front wall\n    p['xlip']=-(p['bar_x']+p['bar_r']-p['D']+0.02)    # front wall at rim height, bin frame mirrored (front -> +x)\n"
    "    p['comb_abs']=comb\n"
    "    if HULL=='new':   # [H2/S1] receiver at the data-sheet comb height\n"
    "        g=HH.geom_params(binkey,p); p['xlip']=-g['xf']; p['zL_abs']=g['zL_front']+p['wheel_r']; p['lip_w']=g['lw']\n"
    "    return p")
# ---- build_xml: pad position (S4 gap), castor fork CG, body geoms, comb pivot, pad size, bin block, keeper
rep("    G=GEO; M=json.load(open(MASSF)); rows=M['rows']",
    "    G=dict(GEO); M=json.load(open(MASSF)); rows=M['rows']\n"
    "    if os.environ.get('H2_PADGAP') and with_bin and HULL=='new':   # [S4] pad set for a nominal wall-to-pad gap on this bin\n"
    "        g_=HH.geom_params(binkey,dict(p,comb_d=0.0)); zp=g_['zL_front']-G['pad_dz']; sb=HH.front_x(g_,zp)-g_['xf']\n"
    "        G['pad_setback']=0.012+sb-float(os.environ['H2_PADGAP']); G['pad_in']=G['pad_setback']-0.012; GEO['_pad_setback_used']=round(G['pad_setback'],4)")
rep("    car=M['carriage'][0]; z0=G['car_zero']-G['nib_h']\n    ca=composite([dict(kg=car['kg'],p=[car['p'][0]-G['face_x'],0,0.0],d=car['d'])],np.zeros(3))",
    "    car=M['carriage'][0]; z0=G['car_zero']-G['nib_h']\n"
    "    _Lt,_nl=G['tooth_len'],G['nib_l']; _pfx=G['face_x']-_Lt-0.004-G['pad_in']-G['face_x']; _pz=G['nib_h']-G['pad_dz']\n"
    "    _sub=[(0.6,np.array([-_Lt+_nl+0.06,0,0])),(0.2,np.array([-0.035,0,0.10])),(0.3,np.array([_pfx+0.02,0,_pz])),(0.4,np.array([_pfx+0.01,0,_pz]))]   # comb, keeper, padbase, pad bodies\n"
    "    _ms=sum(k for k,_ in _sub); _tgt=np.array([car['p'][0]-G['face_x'],0,G['car_dz']]); _c=(car['kg']*_tgt-sum(k*v for k,v in _sub))/(car['kg']-_ms)\n"
    "    ca=composite([dict(kg=car['kg']-_ms,p=list(_c),d=car['d'])],np.zeros(3))   # [H2] carriage total incl. comb/pad bodies = params item")
rep('<inertial mass="1.0" pos="-0.02 0 0.08" diaginertia="0.004 0.004 0.002"/>','<inertial mass="1.0" pos="0.075 0 0.05" diaginertia="0.004 0.004 0.002"/>')
rep('''    body=f\'\'\'<geom name="tray" type="box" pos="0.72 0 0.285" size="0.025 0.355 0.025" contype="0" conaffinity="1" mass="0"/>
<geom name="bumper" type="box" pos="0.865 0 0.25" size="0.015 0.40 0.04" contype="0" conaffinity="1" mass="0"/>
<geom name="rearface" type="box" pos="0.45 0 0.80" size="0.025 0.245 0.50" contype="2" conaffinity="0" mass="0" rgba="0.4 0.4 0.45 0.4"/>\'\'\'''',
'''    body=f\'\'\'<geom name="tray" type="box" pos="0.80 0 0.285" size="0.025 0.355 0.025" contype="0" conaffinity="1" mass="0"/>
<geom name="bumper" type="box" pos="0.945 0 0.25" size="0.015 0.45 0.04" contype="0" conaffinity="1" mass="0"/>
<geom name="rearface" type="box" pos="0.56 0 0.80" size="0.025 0.245 0.50" contype="2" conaffinity="0" mass="0" rgba="0.4 0.4 0.45 0.4"/>\'\'\'''')
rep('<geom name="padg" type="box" pos="0.01 0 0" size="0.01 0.15 0.05" contype="2" conaffinity="0" friction="0.3" mass="0" rgba="0.1 0.1 0.1 1"/>',
    '<geom name="padg" type="box" pos="0.01 0 0" size="0.01 {G[\'pad_hw\']} {G[\'pad_hh\']}" contype="2" conaffinity="0" friction="{G[\'pad_mu\']}" mass="0" rgba="0.1 0.1 0.1 1"/>')
# comb: B2's self-aligning pivot (b2/simB2.py lines verbatim)
rep('''<geom name="tooth" type="box" pos="{-(Lt-nl)/2:.4f} 0 -0.005" size="{(Lt-nl)/2:.4f} {hw} 0.005" contype="6" conaffinity="0" friction="{p.get('mu_hook',0.35)}" mass="0" rgba="0.2 0.2 0.25 1"/>
<geom name="nib" type="box" pos="{-Lt+nl/2:.4f} 0 {nh/2-0.005:.4f}" size="{nl/2:.4f} {hw} {nh/2+0.005:.4f}" contype="6" conaffinity="0" friction="{p.get('mu_hook',0.35)}" mass="0" rgba="1 0.45 0.1 1"/>''',
'''{comb_open}<geom name="tooth" type="box" pos="{-(Lt-nl)/2-cx0:.4f} 0 -0.005" size="{(Lt-nl)/2:.4f} {hw} 0.005" contype="6" conaffinity="0" friction="{p.get('mu_hook',0.35)}" mass="0" rgba="0.2 0.2 0.25 1"/>
<geom name="nib" type="box" pos="{-Lt+nl/2-cx0:.4f} 0 {nh/2-0.005:.4f}" size="{nl/2:.4f} {hw} {nh/2+0.005:.4f}" contype="6" conaffinity="0" friction="{p.get('mu_hook',0.35)}" mass="0" rgba="1 0.45 0.1 1"/>{HH.keeper_xml(G,cx0) if KEEPER2 else ''}{comb_close}''')
rep("    qref=-G['pad_pre']/G['pad_k']\n",
    "    cx0=-Lt+nl; ky=float(os.environ.get('CMP_PIV_K','60')); kr=float(os.environ.get('CMP_PIV_KR','400'))   # [H2] B2 fw_pivot comb\n"
    "    comb_open=(f'<body name=\"comb\" pos=\"{cx0:.4f} 0 0\"><joint name=\"combyaw\" type=\"hinge\" axis=\"0 0 1\" range=\"-4 4\" stiffness=\"{ky}\" damping=\"1.5\" solreflimit=\"0.004 1\"/>'\n"
    "               f'<joint name=\"combroll\" type=\"hinge\" axis=\"1 0 0\" range=\"-3 3\" stiffness=\"{kr}\" damping=\"3\" solreflimit=\"0.004 1\"/><inertial mass=\"0.6\" pos=\"0.06 0 0\" diaginertia=\"0.01 0.002 0.01\"/>')\n"
    "    comb_close='</body>'\n"
    "    qref=-G['pad_pre']/G['pad_k']\n")
# bin block
a=src.find("    binb=''; bm=0.0\n    if with_bin:"); b=src.find("    else: asset=''",a); assert a>0 and b>a
old_block=src[a:b]
src=src[:a]+("    binb=''; bm=0.0\n    if with_bin and HULL=='new':\n"
             "        asset,binb,bm,_info=HH.bin_xml(binkey,p,'front',mu,fr,(crr_bin if crr_bin is not None else crr),p.get('mu_hook',0.35),box_I,inert)\n"
             "    elif with_bin:"+old_block.split("    if with_bin:",1)[1])+src[b:]
rep("<position name=\"padact\" joint=\"padext\" kp=\"100000\" kv=\"3000\" forcerange=\"-1500 1500\"/></actuator></mujoco>'''",
    "<position name=\"padact\" joint=\"padext\" kp=\"100000\" kv=\"3000\" forcerange=\"-1500 1500\"/>{HH.keeper_act() if KEEPER2 else ''}</actuator></mujoco>'''")
# ---- SimB: names, pair over both hull meshes, keeper init, per-wheel clearance
rep("        if s.with_bin: names+=['binwheelL','binwheelR','binhull','bar','ledge','rim','lid']\n        s.gid={n:Gd(n) for n in names}",
    "        if s.with_bin: names+=['binwheelL','binwheelR','binhull','bar','ledge','rim','lid','binhull_lo','hrim']\n        names+=['kbar']\n        s.gid={n:Gd(n) for n in names}; HH.apply_overrides(s)")
rep("        s.keeper_cmd=6.0; s.d.qpos[s.jq('keeper')]=1.4\n","        s.keeper_cmd=6.0; s.d.qpos[s.jq('keeper')]=1.4\n        if KEEPER2: HH.keeper_init(s)\n")
rep("    def pair(s,a,b):\n        ga,gb=s.gid.get(a,-9),s.gid.get(b,-9); return s._pairs.get((min(ga,gb),max(ga,gb)),0.0)",
    "    def pair(s,a,b):\n        ga,gb=s.gid.get(a,-9),s.gid.get(b,-9)\n        if ga<0 or gb<0: return 0.0\n        v=s._pairs.get((min(ga,gb),max(ga,gb)),0.0)\n"
    "        if 'binhull' in (a,b) and HULL=='new': o=b if a=='binhull' else a; v+=s.pair('binhull_lo',o)\n        return v\n"
    "    def wheel_clear_each(s):\n        wr=s.p['wheel_r']; return [float(s.d.xpos[s.bid[w]][2])-wr for w in ('bwL','bwR')]")
# ---- firmware: dock stop on the pad counts as a squaring contact (the gap check still applies); rim catch 25 mm; FH1; FH2; no keeper
rep("    good=why in ('tof','contact') and gap<=0.010","    good=why in ('tof','contact','pad') and gap<=0.010   # [H2] pad = carriage face contact")
rep("            if q<q_ledge-0.012: st['abort']","            if q<q_ledge-G['rimcatch']: st['abort']")
rep("""    R.phase='2b Pad extends during the +100 mm lift (bin hangs against it before the keeper closes)'; set_pad(S,0.0)   # [F7] pad first, then keeper
    tgt=G['lift_range']-0.002 if 'liftmax' in FIX else min(st['zc']+G['lift_extra1'],G['lift_range']-0.002)   # [FH1] lift to the stroke end
    R.ramp_lift(tgt,0.03); R.run_for(0.8)
    R.phase='3 Keeper closes on the handle bar'; S.keeper_cmd=-6.0; R.run_for(1.2)""",
"""    # [H2-FH1] keep lifting until BOTH bin-wheel clearance sensors read clear and the comb is >= fh1_rise above load-on; stroke end regardless
    srng=np.random.default_rng(seed+77); nz=[float(srng.normal(0,G['wclr_sig'])),float(srng.normal(0,G['wclr_sig']))]
    def sens(): w=S.wheel_clear_each(); return [w[0]+nz[0],w[1]+nz[1]]
    def both_clear(): return min(sens())>=G['wclr']
    R.phase='2b FH1: lift until both clearance sensors clear and +%.0f mm'%(G['fh1_rise']*1000)
    R.ramp_lift(G['lift_range']-0.002,0.03,cond=lambda: S.lift_q()-st['zc']>=G['fh1_rise'] and both_clear(),Tmax=20); R.run_for(0.8)
    R.fh1_q=round(S.lift_q(),3)
    if KEEPER2: HH.keeper_close(S,R)""")
rep("""    ss=seat_sw(); keep_ok=True   # Rev H: no handle-bar keeper; claim = load + comb switches
    claim=bool(rise>60 and ss and keep_ok)
    if 'wheelchk' in FIX:   # [FH2] rear camera checks both bin wheels >= 30 mm clear (sigma 5 mm) before the claim; else lower + report
        wc=S.wheel_clear()+float(np.random.default_rng(seed+77).normal(0,0.005)); out['wheel_cam_mm']=round(wc*1000,1)
        claim=claim and wc>0.030""",
"""    ss=seat_sw(); keep_ok=True   # Rev H2: no handle-bar keeper
    sv=sens(); out['wheel_sens_mm']=[round(1000*v,1) for v in sv]; out['fh1_q']=R.fh1_q
    claim=bool(rise>60 and ss and min(sv)>=G['wclr'])   # [H2-FH2] seat switch AND both clearance sensors clear""")
rep("R.phase='3x No claim: keeper open, pad retract, comb down, back off'; S.keeper_cmd=6.0;",
    "R.phase='3x No claim: keeper open, pad retract, comb down, back off'; S.keeper_cmd=6.0; HH.keeper_open(S) if KEEPER2 else None;")
rep("R.phase='11 SD2: keeper opens, pad retracts, comb to 25 mm under the rim'; S.keeper_cmd=6.0;",
    "R.phase='11 SD2: keeper opens, pad retracts, comb to 25 mm under the rim'; S.keeper_cmd=6.0; HH.keeper_open(S) if KEEPER2 else None;")
open(os.path.join(H,'simH2.py'),'w').write(src); print('wrote simH2.py',len(src))
